package ma.fstt.dao;
import ma.fstt.model.*; import ma.fstt.persistence.JPAUtil; import java.util.*;
public class ClientDAO extends BaseDAO { public List<Client> tous(){try(var em=JPAUtil.getEmf().createEntityManager()){return em.createQuery("SELECT c FROM Client c ORDER BY c.id DESC",Client.class).getResultList();}} public Client trouver(Long id){try(var em=JPAUtil.getEmf().createEntityManager()){return em.find(Client.class,id);}} public void ajouter(Client c){tx(em->em.persist(c));} public void modifier(Long id,String n,String e){tx(em->{Client c=em.find(Client.class,id);if(c!=null){c.setNom(n);c.setEmail(e);}});} public void supprimer(Long id){tx(em->{Client c=em.find(Client.class,id);if(c!=null){if(!c.getCommandes().isEmpty())throw new IllegalStateException("Client déjà associé à des commandes.");em.remove(c);}});} }